import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import Razorpay from 'razorpay';

const TEST_KEY_PREFIX = 'rzp_test_';

/**
 * Constructs the Razorpay SDK client lazily, on first real use, rather than
 * eagerly at module init. RAZORPAY_KEY_ID/RAZORPAY_KEY_SECRET are the user's
 * own real credentials (pasted in by them, never generated by us) — making
 * this eager would mean the whole service refuses to boot (health check
 * included) until those are configured. Failing only when a charge is
 * actually attempted is a much smaller blast radius, and lets everything else
 * in this service (auth, subscriptions, module access, the webhook receiver)
 * run and be verified independently of whether Razorpay keys are set yet.
 */
@Injectable()
export class RazorpayClientFactory {
  private client: Razorpay | null = null;

  constructor(private readonly configService: ConfigService) {}

  getClient(): Razorpay {
    if (this.client) return this.client;

    const keyId = this.configService.get<string>('RAZORPAY_KEY_ID');
    const keySecret = this.configService.get<string>('RAZORPAY_KEY_SECRET');

    if (!keyId || !keySecret) {
      throw new Error(
        'RAZORPAY_KEY_ID / RAZORPAY_KEY_SECRET are not configured. Paste your Razorpay ' +
          "TEST-mode keys into this service's .env before creating a billing order.",
      );
    }

    if (!keyId.startsWith(TEST_KEY_PREFIX)) {
      throw new Error(
        `RAZORPAY_KEY_ID must be a Razorpay TEST-mode key (starting with "${TEST_KEY_PREFIX}") — ` +
          'live keys are not permitted yet.',
      );
    }

    this.client = new Razorpay({ key_id: keyId, key_secret: keySecret });
    return this.client;
  }
}
